import React, { useState, useMemo } from 'react';
import {
  Users,
  Search,
  Plus,
  Edit,
  Trash2,
  FileSpreadsheet,
  FileText,
  Mail,
  Phone,
  MapPin,
  Building,
  CheckCircle,
} from 'lucide-react';
import { Client } from '../types';
import { ClientModal } from './ClientModal';
import { exportTableToXlsx } from '../utils/excelExporter';
import { formatDate } from '../utils/formatters';
import { usePersistentSort, SortableHeader } from '../hooks/usePersistentSort';

interface ClientsManagerProps {
  clients: Client[];
  onSaveClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onViewLedger: (clientId: string) => void;
  onNewDocForClient: (clientId: string) => void;
}

export const ClientsManager: React.FC<ClientsManagerProps> = ({
  clients,
  onSaveClient,
  onDeleteClient,
  onViewLedger,
  onNewDocForClient,
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Persistent multi-column table sorting hook
  const { sortConfig, toggleSort, sortData } = usePersistentSort<Client>(
    'clients_directory',
    'name',
    'asc'
  );

  const openCreateModal = () => {
    setEditingClient(null);
    setIsModalOpen(true);
  };

  const openEditModal = (client: Client) => {
    setEditingClient(client);
    setIsModalOpen(true);
  };

  const handleModalSave = (clientToSave: Client) => {
    onSaveClient(clientToSave);
    setIsModalOpen(false);
  };

  const filteredClients = useMemo(() => {
    return clients.filter((c) => {
      if (!searchQuery.trim()) return true;
      const q = searchQuery.toLowerCase();
      return (
        c.name.toLowerCase().includes(q) ||
        (c.contactPerson && c.contactPerson.toLowerCase().includes(q)) ||
        (c.kraPin && c.kraPin.toLowerCase().includes(q)) ||
        (c.email && c.email.toLowerCase().includes(q)) ||
        (c.phone && c.phone.toLowerCase().includes(q))
      );
    });
  }, [clients, searchQuery]);

  const sortedClients = useMemo(() => {
    return sortData(filteredClients, {
      name: (c) => c.name,
      contactPerson: (c) => c.contactPerson || '',
      kraPin: (c) => c.kraPin || '',
      phone: (c) => c.phone || '',
      address: (c) => c.address || '',
      createdAt: (c) => c.createdAt || '',
    });
  }, [filteredClients, sortData]);

  const handleExportXlsx = async () => {
    if (filteredClients.length === 0) {
      alert('No clients found to export.');
      return;
    }

    const columns = [
      { header: 'Client / Organization Name', key: 'name', type: 'text' as const, width: 28 },
      { header: 'Contact Person', key: 'contactPerson', type: 'text' as const, width: 22 },
      { header: 'KRA PIN', key: 'kraPin', type: 'code' as const, width: 15 },
      { header: 'Phone Number', key: 'phone', type: 'code' as const, width: 16 },
      { header: 'Email Address', key: 'email', type: 'text' as const, width: 25 },
      { header: 'Physical / Postal Address', key: 'address', type: 'text' as const, width: 30 },
      { header: 'Registration Date', key: 'createdAt', type: 'date' as const, width: 14 },
    ];

    const data = filteredClients.map((c) => ({
      name: c.name,
      contactPerson: c.contactPerson || '-',
      kraPin: c.kraPin || '-',
      phone: c.phone || '-',
      email: c.email || '-',
      address: c.address || '-',
      createdAt: c.createdAt || '-',
    }));

    await exportTableToXlsx({
      title: 'Client Directory & Contact Roster',
      sheetName: 'Clients_Directory',
      columns,
      data,
      summaryRow: false,
      filename: `HotelDamview_Clients_Roster_${formatDate()}.xlsx`,
    });
  };

  return (
    <div className="p-6 max-w-7xl mx-auto space-y-5">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-stone-200 pb-4">
        <div>
          <h1 className="text-2xl font-bold text-stone-900 tracking-tight flex items-center gap-2">
            <Users className="w-6 h-6 text-amber-700" />
            Client Directory &amp; Profiles
          </h1>
          <p className="text-sm text-stone-600">
            Registered corporate clients, government agencies, safari groups, and private event guests.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={handleExportXlsx}
            className="px-3 py-2 bg-stone-100 hover:bg-stone-200 text-stone-700 text-xs font-bold rounded flex items-center gap-1.5 border border-stone-300 transition-colors cursor-pointer"
            title="Export client roster to formatted Excel (.xlsx)"
          >
            <FileSpreadsheet className="w-3.5 h-3.5 text-emerald-600" />
            <span>Export Excel (.xlsx)</span>
          </button>

          <button
            type="button"
            onClick={openCreateModal}
            className="px-3.5 py-2 bg-stone-900 hover:bg-stone-800 text-amber-400 text-xs font-bold rounded flex items-center gap-1.5 shadow-xs transition-colors cursor-pointer"
          >
            <Plus className="w-4 h-4 text-amber-400" />
            Register New Client
          </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="bg-white border border-stone-200 rounded p-4 shadow-xs flex items-center justify-between">
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 text-stone-400 absolute left-3 top-2.5" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search by client name, KRA PIN, contact person, email..."
            className="w-full pl-9 pr-3 py-1.5 text-xs border border-stone-300 rounded focus:outline-none focus:ring-1 focus:ring-stone-500 text-stone-900 bg-stone-50/50"
          />
        </div>

        <span className="text-xs text-stone-500 font-medium">
          Total Registered: <strong className="text-stone-900">{clients.length}</strong>
        </span>
      </div>

      {/* Client Datatable */}
      <div className="bg-white border border-stone-200 rounded shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs border-collapse">
            <thead>
              <tr className="bg-stone-100 border-b border-stone-200 text-stone-700 font-bold">
                <SortableHeader column="name" label="Client / Organization" currentSort={sortConfig} onSort={toggleSort} />
                <SortableHeader column="contactPerson" label="Contact Person" currentSort={sortConfig} onSort={toggleSort} />
                <SortableHeader column="kraPin" label="KRA PIN" currentSort={sortConfig} onSort={toggleSort} />
                <SortableHeader column="phone" label="Phone & Email" currentSort={sortConfig} onSort={toggleSort} />
                <SortableHeader column="address" label="Physical Address" currentSort={sortConfig} onSort={toggleSort} />
                <th className="py-2.5 px-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-stone-200">
              {sortedClients.length > 0 ? (
                sortedClients.map((client) => (
                  <tr key={client.id} className="hover:bg-stone-50/80 transition-colors">
                    <td className="py-2.5 px-3">
                      <div className="font-bold text-stone-900 text-sm">{client.name}</div>
                      <div className="text-[10px] text-stone-400">Reg: {client.createdAt}</div>
                    </td>
                    <td className="py-2.5 px-3 font-medium text-stone-800">
                      {client.contactPerson || '-'}
                    </td>
                    <td className="py-2.5 px-3">
                      {client.kraPin ? (
                        <span className="font-mono bg-stone-100 px-1.5 py-0.5 rounded text-stone-800 border border-stone-200 font-semibold">
                          {client.kraPin}
                        </span>
                      ) : (
                        <span className="text-stone-400 italic">Not set</span>
                      )}
                    </td>
                    <td className="py-2.5 px-3">
                      <div className="text-stone-800 font-medium">{client.phone || '-'}</div>
                      <div className="text-stone-500 text-[11px]">{client.email || '-'}</div>
                    </td>
                    <td className="py-2.5 px-3 text-stone-600 max-w-xs truncate">
                      {client.address || '-'}
                    </td>
                    <td className="py-2.5 px-3 text-right">
                      <div className="inline-flex items-center justify-end gap-1.5">
                        {/* View Ledger */}
                        <button
                          type="button"
                          onClick={() => onViewLedger(client.id)}
                          className="px-2 py-1 bg-amber-50 text-amber-900 hover:bg-amber-100 border border-amber-300 rounded font-semibold text-[11px] flex items-center gap-1"
                          title="View Statement of Account / Ledger"
                        >
                          <FileSpreadsheet className="w-3 h-3" />
                          Ledger
                        </button>

                        {/* New Document */}
                        <button
                          type="button"
                          onClick={() => onNewDocForClient(client.id)}
                          className="px-2 py-1 bg-stone-100 text-stone-800 hover:bg-stone-200 rounded font-semibold text-[11px] flex items-center gap-1"
                          title="Create New Document for Client"
                        >
                          <FileText className="w-3 h-3" />
                          Bill
                        </button>

                        {/* Edit */}
                        <button
                          type="button"
                          onClick={() => openEditModal(client)}
                          className="p-1 text-stone-500 hover:text-stone-900 hover:bg-stone-100 rounded"
                          title="Edit Client"
                        >
                          <Edit className="w-3.5 h-3.5" />
                        </button>

                        {/* Delete */}
                        <button
                          type="button"
                          onClick={() => onDeleteClient(client.id)}
                          className="p-1 text-stone-400 hover:text-rose-600 hover:bg-rose-50 rounded"
                          title="Delete Client"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : clients.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-14 text-center">
                    <div className="flex flex-col items-center justify-center max-w-md mx-auto text-center px-4">
                      <div className="w-12 h-12 rounded-full bg-stone-100 flex items-center justify-center text-stone-400 mb-3 border border-stone-200">
                        <Users className="w-6 h-6" />
                      </div>
                      <h4 className="text-sm font-bold text-stone-800 mb-1">
                        No Client Records Found
                      </h4>
                      <p className="text-xs text-stone-500 leading-relaxed mb-4">
                        New applications initialize clean with zero default dummy clients. Once connected to your Google Sheet, client profiles specific to your business will automatically synchronize here in real time.
                      </p>
                      <button
                        type="button"
                        onClick={openCreateModal}
                        className="px-3.5 py-1.5 bg-amber-500 hover:bg-amber-400 text-stone-950 font-bold rounded-lg text-xs flex items-center gap-1.5 shadow-xs transition-colors cursor-pointer"
                      >
                        <Plus className="w-3.5 h-3.5" />
                        <span>Register First Client Profile</span>
                      </button>
                    </div>
                  </td>
                </tr>
              ) : (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-stone-400 italic">
                    No clients match your search query "{searchQuery}".
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* GUARDED REUSABLE CLIENT MODAL */}
      <ClientModal
        isOpen={isModalOpen}
        client={editingClient}
        onClose={() => setIsModalOpen(false)}
        onSaveClient={handleModalSave}
      />
    </div>
  );
};
